def expand(scene):
    out = scene
    for tok, val, short in (("{C}", C, "the caveman"), ("{P}", P, "stickman-style")):
        if tok in out:
            k = out.index(tok)
            out = out[:k] + val + out[k + len(tok):].replace(tok, short)
    out = re.sub(r"(^|[.!?] )([a-z])", lambda m: m.group(1) + m.group(2).upper(), out)
    return out

def prompt(ts, scene):
    return f"[{ts}] {expand(scene)} {STYLE}"

